        ground=Math.max(0,hAt(v.x,v.z)),
        altitude=Number.isFinite(v.alt)?v.alt:(v.o?.position?.y??ground);
  P.x=v.x+Math.cos(v.hd)*side*1.8;
  P.z=v.z-Math.sin(v.hd)*side*1.8;
  P.hd=v.hd;P.y=altitude;
